import java.util.*;public class Parser {public static Map<String,String> parse(String text){var out=new HashMap<String,String>();for(String raw:text.split("\\R")){String line=raw.trim();if(line.isEmpty()||line.startsWith("#"))continue;int split=line.indexOf('=');if(split<1)throw new IllegalArgumentException();String key=line.substring(0,split).trim();if(key.isEmpty()||out.putIfAbsent(key,line.substring(split+1).trim())!=null)throw new IllegalArgumentException();}return out;}}
